START TRANSACTION;
     'https://alternative.me/crypto/fear-and-greed-index/',
     'Free API including all available history. Commercial use is allowed with attribution immediately next to the displayed data. Do not impersonate the provider. Terms: https://alternative.me/crypto/fear-and-greed-index/.',
     'Fear & Greed Index: Alternative.me, https://alternative.me/crypto/fear-and-greed-index/.', 1),
    ('open_bitcoin_metrics_obm', 'Open Bitcoin Metrics (OBM)', 'csv_archive',
     'https://github.com/diegorllanos/open-bitcoin-metrics',
     'Data and documentation CC BY 4.0. Preserve author, source, license and release metadata. No substitution of methods without explicit versioning.',
     'Open Bitcoin Metrics (OBM), Diego R. Llanos. Data CC BY 4.0, https://creativecommons.org/licenses/by/4.0/. Source: https://github.com/diegorllanos/open-bitcoin-metrics.', 1)
ON DUPLICATE KEY UPDATE display_name = VALUES(display_name), provider_type = VALUES(provider_type),
    base_url = VALUES(base_url), license_note = VALUES(license_note), attribution_text = VALUES(attribution_text), is_active = VALUES(is_active);


ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),provider_type=VALUES(provider_type),base_url=VALUES(base_url),license_note=VALUES(license_note),attribution_text=VALUES(attribution_text),is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE source_id=VALUES(source_id),category=VALUES(category),display_name=VALUES(display_name),unit=VALUES(unit),source_hint=VALUES(source_hint),source_series=VALUES(source_series),description=VALUES(description),methodology_note=VALUES(methodology_note),native_frequency=VALUES(native_frequency),observation_kind=VALUES(observation_kind),calendar_type=VALUES(calendar_type),expected_start=VALUES(expected_start),display_order=VALUES(display_order),is_overview=VALUES(is_overview);
ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),display_order=VALUES(display_order),native_frequency=VALUES(native_frequency),calendar_type=VALUES(calendar_type),expected_start=VALUES(expected_start);
UPDATE bitcoin_metrics SET is_overview=0 WHERE metric_id NOT IN ('price_usd','price_eur','market_cap_usd','spot_volume_usd','price_sma_200d_usd','price_sma_200w_usd','mayer_multiple','return_1d','return_7d','return_30d','return_90d','return_1y','return_ytd_pct','cagr_3y_pct','volatility_30d','volatility_90d','drawdown_ath','mvrv_ratio','realized_cap_usd','realized_price_usd','nupl_pct','puell_multiple','transactions_count','active_addresses','addresses_nonzero_balance','utxo_count','block_weight_mwu','blockspace_utilization_pct','supply_btc','issued_btc_daily','inflation_rate_pct','block_reward_btc','blocks_until_halving','hashrate_eh_s','difficulty','blocks_count','block_interval_7d_min','miner_revenue_usd','hashprice_usd_ph_day','fees_total_btc','fees_average_usd','fee_share_miner_revenue_pct','exchange_balance_btc','exchange_inflow_btc','exchange_outflow_btc','exchange_netflow_btc','coin_days_destroyed','liveliness','fear_greed_index','futures_open_interest_usd');
COMMIT;
